// Sau erasure cả hai đều là copy(List, List) -> lỗi biên dịch nếu overload
static <T> void copy(List<? super T> dst, List<? extends T> src) {
    for (T t : src) dst.add(t);   // src là producer -> extends; dst là consumer -> super
}

